import numpy as np

def problem(x: np.ndarray) -> float:
    x1, x2, x3 = x
    return x1**2 + x2**2 + x3**2 + 0.3*x1*x2 + np.exp(0.2*x1)

import numpy as np

def problem(x: np.ndarray) -> float:
    n = x.shape[0]
    term1 = np.sum(x**2)
    term2 = 0.0
    for i in range(n):
        for j in range(i + 1, n):
            term2 += (x[i] * x[j])
    term3 = np.exp(x[0])
    return (term1 + 0.5 * term2 + 0.05 * term3)**2

import numpy as np

def problem(x: np.ndarray) -> float:
    x1, x2, x3 = x
    return 0.5 * (x1**2 + x2**2 + x3**2) + 0.2 * (x1 * x2 + x2 * x3 + x1 * x3) + 0.1 * np.exp(0.5 * x1)

import numpy as np

def problem(x: np.ndarray) -> float:
    n = x.shape[0]
    term1 = np.sum(x**2)
    term2 = 0.0
    for i in range(n):
        for j in range(i + 1, n):
            term2 += (x[i] * x[j])
    term3 = np.exp(x[0])
    term4 = np.sin(x[2]**2)
    term5 = np.sum(x**3)
    return (0.5 * term1 + 0.1 * term5 + 0.1* term2 + 0.1 * term3 + 0.2*term4)
